// Run one GEMM kernel from kernels/ (or any .metal file with the same
// buffer layout) on N x N x N inputs and report the median GPU time.
// Generated by Claude (Opus 5.5); see README.md.
//
// usage: run_kernel <file.metal> <function> <gridX> <gridY> <tgX> <tgY> [iters] [N]
//
// Each timed dispatch is its own command buffer labelled "<function>#<i>",
// so profile_kernel.sh can find it in an Instruments trace. The warm-up
// dispatch is labelled "warmup". Timing uses gpuStartTime/gpuEndTime.
import Foundation
import Metal

let args = CommandLine.arguments
guard args.count >= 7 else {
  print("usage: run_kernel file.metal function gridX gridY tgX tgY [iters] [N]")
  exit(1)
}
let path = args[1], fname = args[2]
let gx = Int(args[3])!, gy = Int(args[4])!, tx = Int(args[5])!, ty = Int(args[6])!
let iters = args.count > 7 ? Int(args[7])! : 10
let n = args.count > 8 ? Int(args[8])! : 4096

let dev = MTLCreateSystemDefaultDevice()!
let src = try! String(contentsOfFile: path, encoding: .utf8)
// TensorOps kernels need the Metal 4 language; keep default options otherwise.
var opts: MTLCompileOptions? = nil
if src.contains("<metal_tensor>") {
  opts = MTLCompileOptions()
  opts!.languageVersion = .version4_0
}
let lib = try! dev.makeLibrary(source: src, options: opts)
let fn = lib.makeFunction(name: fname)!
let pso = try! dev.makeComputePipelineState(function: fn)
print("\(fname): maxTotalThreadsPerThreadgroup=\(pso.maxTotalThreadsPerThreadgroup) "
  + "threadExecutionWidth=\(pso.threadExecutionWidth) "
  + "staticThreadgroupMemoryLength=\(pso.staticThreadgroupMemoryLength)")

let count = n * n
var a = [Float](repeating: 0, count: count)
var b = [Float](repeating: 0, count: count)
for i in 0..<count { a[i] = Float.random(in: -1...1); b[i] = Float.random(in: -1...1) }
let bufA = dev.makeBuffer(bytes: a, length: count * 4, options: .storageModeShared)!
let bufB = dev.makeBuffer(bytes: b, length: count * 4, options: .storageModeShared)!
let bufC = dev.makeBuffer(length: count * 4, options: .storageModeShared)!
var shape: [UInt32] = [UInt32(n), UInt32(n), UInt32(n)]

let q = dev.makeCommandQueue()!
func run(label: String) -> Double {
  let cb = q.makeCommandBuffer()!
  cb.label = label
  let enc = cb.makeComputeCommandEncoder()!
  enc.label = label
  enc.setComputePipelineState(pso)
  enc.setBuffer(bufA, offset: 0, index: 0)
  enc.setBuffer(bufB, offset: 0, index: 1)
  enc.setBuffer(bufC, offset: 0, index: 2)
  enc.setBytes(&shape, length: 12, index: 3)
  enc.dispatchThreadgroups(MTLSize(width: gx, height: gy, depth: 1),
    threadsPerThreadgroup: MTLSize(width: tx, height: ty, depth: 1))
  enc.endEncoding()
  cb.commit()
  cb.waitUntilCompleted()
  if let e = cb.error { print("error: \(e)"); exit(1) }
  return (cb.gpuEndTime - cb.gpuStartTime) * 1000
}

_ = run(label: "warmup")
// spot-check a few outputs against a CPU dot product
let C = bufC.contents().bindMemory(to: Float.self, capacity: count)
var maxErr: Float = 0
for s in 0..<16 {
  let i = (s * 257) % n, j = (s * 911 + 13) % n
  var ref: Float = 0
  for p in 0..<n { ref += a[i * n + p] * b[p * n + j] }
  maxErr = max(maxErr, abs(ref - C[i * n + j]))
}
print("spot-check max abs error: \(maxErr)")

var times: [Double] = []
for it in 0..<iters {
  times.append(run(label: "\(fname)#\(it)"))
  usleep(20_000)
}
times.sort()
let med = times[times.count / 2]
let gflops = 2.0 * Double(n) * Double(n) * Double(n) / (med * 1e6)
print(String(format: "%@: median %.2f ms, %.0f GFLOP/s (GPU time, %d iters)", fname, med, gflops, iters))
